514→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
515→// checkpoint branch. It parses the two-level directory structure
516→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
517→func CheckpointIDs(t *testing.T, dir string) []string {
518→	t.Helper()
519→	out := gitOutputSafe(dir, "ls-tree", "-r", "--name-only", "entire/checkpoints/v1")
520→	if out == "" {
521→		return nil
522→	}
523→	seen := map[string]bool{}
524→	var ids []string
525→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
526→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
527→		parts := strings.Split(line, "/")
528→		if len(parts) == 3 && parts[2] == "metadata.json" {
529→			id := parts[0] + parts[1]
530→			if !seen[id] {
531→				seen[id] = true
532→				ids = append(ids, id)
533→			}
534→		}
535→	}
536→	return ids
537→}
