574→
575→// WaitForSessionMetadata polls until session metadata exists on the checkpoint
576→// branch for the given checkpoint ID and session index, then returns it.
577→// This handles the race where the checkpoint branch advances before session
578→// metadata is fully committed.
579→func WaitForSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int, timeout time.Duration) SessionMetadata {
580→	t.Helper()
581→
582→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
583→	blob := "entire/checkpoints/v1:" + path
584→
585→	deadline := time.Now().Add(timeout)
586→	for time.Now().Before(deadline) {
587→		raw := gitOutputSafe(dir, "show", blob)
588→		if raw != "" {
589→			var meta SessionMetadata
590→			if err := json.Unmarshal([]byte(raw), &meta); err != nil {
591→				t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
592→			}
593→			return meta
594→		}
595→		time.Sleep(500 * time.Millisecond)
596→	}
597→	t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
598→	return SessionMetadata{}
599→}
