418→
419→	// Write an existing hooks file with a user entry that has cwd, timeoutSec, and env.
420→	existingJSON := `{
421→  "version": 1,
422→  "hooks": {
423→    "agentStop": [
424→      {
425→        "type": "command",
426→        "bash": "echo user stop",
427→        "cwd": "/home/user/project",
428→        "timeoutSec": 30,
429→        "env": {
430→          "MY_VAR": "hello",
431→          "OTHER": "world"
432→        }
433→      }
434→    ]
435→  }
436→}`
437→	githubHooksDir := filepath.Join(tempDir, ".github", "hooks")
438→	if err := os.MkdirAll(githubHooksDir, 0o755); err != nil {
439→		t.Fatal(err)
440→	}
441→	if err := os.WriteFile(filepath.Join(githubHooksDir, HooksFileName), []byte(existingJSON), 0o644); err != nil {
442→		t.Fatal(err)
443→	}
