447→	count, err := ag.InstallHooks(context.Background(), false, false)
448→	if err != nil {
449→		t.Fatalf("InstallHooks() error = %v", err)
450→	}
451→	if count == 0 {
452→		t.Fatal("InstallHooks() installed 0 hooks, expected > 0")
453→	}
454→
455→	// Re-read the file and parse hook entries.
456→	data, err := os.ReadFile(filepath.Join(githubHooksDir, HooksFileName))
457→	if err != nil {
458→		t.Fatalf("failed to read hooks file: %v", err)
459→	}
460→
461→	var rawFile map[string]json.RawMessage
462→	if err := json.Unmarshal(data, &rawFile); err != nil {
463→		t.Fatalf("failed to parse hooks file: %v", err)
464→	}
465→
466→	var rawHooks map[string]json.RawMessage
467→	if err := json.Unmarshal(rawFile["hooks"], &rawHooks); err != nil {
468→		t.Fatalf("failed to parse hooks: %v", err)
469→	}
470→
471→	var agentStopEntries []CopilotHookEntry
472→	if err := json.Unmarshal(rawHooks["agentStop"], &agentStopEntries); err != nil {
473→		t.Fatalf("failed to parse agentStop entries: %v", err)
474→	}
475→
476→	// Find the user's entry (not the Entire entry).
477→	var userEntry *CopilotHookEntry
478→	for i := range agentStopEntries {
