501→		t.Errorf("env[MY_VAR] = %q, want %q", userEntry.Env["MY_VAR"], "hello")
502→	}
503→	if userEntry.Env["OTHER"] != "world" {
504→		t.Errorf("env[OTHER] = %q, want %q", userEntry.Env["OTHER"], "world")
505→	}
